import{_ as a,c as e,b as s,o as t}from"./app-90veb4I1.js";const l={};function p(o,n){return t(),e("div",null,n[0]||(n[0]=[s(`<h2 id="logical-operations" tabindex="-1"><a class="header-anchor" href="#logical-operations"><span>Logical Operations</span></a></h2><p>These functions allow you to perform element-wise logical comparisons:</p><h3 id="_1-mad-equal-a-b" tabindex="-1"><a class="header-anchor" href="#_1-mad-equal-a-b"><span>1. <code>mad.equal(a, b)</code></span></a></h3><p>Checks element-wise equality:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of the same shape</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Boolean array of comparisons</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> equal <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">equal</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [true, false]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-mad-greater-a-b" tabindex="-1"><a class="header-anchor" href="#_2-mad-greater-a-b"><span>2. <code>mad.greater(a, b)</code></span></a></h3><p>Checks if elements in <code>a</code> are greater than corresponding elements in <code>b</code>:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of the same shape</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Boolean array</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> greater <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">greater</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [true, false]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-mad-where-condition-a-b" tabindex="-1"><a class="header-anchor" href="#_3-mad-where-condition-a-b"><span>3. <code>mad.where(condition, a, b)</code></span></a></h3><p>Returns elements from <code>a</code> where the condition is true, otherwise from <code>b</code>:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">condition</td><td style="text-align:center;">Array</td><td style="text-align:center;">Boolean mask</td></tr><tr><td style="text-align:center;">a, b</td><td style="text-align:center;">Array</td><td style="text-align:center;">Arrays of values</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Resulting values from <code>a</code> or <code>b</code></td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> where <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">where</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [1, 4]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,17)]))}const c=a(l,[["render",p]]),r=JSON.parse('{"path":"/om-functions/logical-operations.html","title":"Logical Operations","lang":"en-US","frontmatter":{"lang":"en-US","title":"Logical Operations","description":"This page will guide you on how to install openmadness"},"headers":[{"level":2,"title":"Logical Operations","slug":"logical-operations","link":"#logical-operations","children":[{"level":3,"title":"1. mad.equal(a, b)","slug":"_1-mad-equal-a-b","link":"#_1-mad-equal-a-b","children":[]},{"level":3,"title":"2. mad.greater(a, b)","slug":"_2-mad-greater-a-b","link":"#_2-mad-greater-a-b","children":[]},{"level":3,"title":"3. mad.where(condition, a, b)","slug":"_3-mad-where-condition-a-b","link":"#_3-mad-where-condition-a-b","children":[]}]}],"git":{"updatedTime":1751456764000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":1,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"om-functions/logical-operations.md"}');export{c as comp,r as data};
